fn parse_number(v: &str) -> Value {
    // argsParser uses `process: Number` which yields NaN for non-numbers; that
    // would later fail the choices check. We mirror by parsing to f64 and, for
    // integer-like values, emitting a JSON number. NaN serializes to null.
    if let Ok(n) = v.parse::<f64>() {
        if n.fract() == 0.0 && n.is_finite() {
            return json!(n as i64);
        }
        json!(n)
    } else {
        Value::Null
    }
}

fn parse_parser_config(v: &str) -> Value {
    match std::fs::read_to_string(v) {
        Ok(contents) => serde_json::from_str(&contents).unwrap_or(Value::Null),
        Err(_) => Value::Null,
    }
}

