fn format_option(opt: &OptDef) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = opt.abbr {
        text.push_str(&format!("-{}, ", abbr));
    } else {
        text.push_str("    ");
    }
    text.push_str("--");
    if opt.flag {
        text.push_str("(no-)");
    }
    text.push_str(&opt.full);
    if let Some(choices) = &opt.choices {
        text.push('=');
        text.push_str(&choices.iter().map(json_to_choice).collect::<Vec<_>>().join("|"));
    } else if let Some(mv) = opt.metavar {
        text.push('=');
        text.push_str(mv);
    }
    if opt.list {
        text.push_str(" ...");
    }
    if opt.default_help.is_some() || opt.default.is_some() || opt.help.is_some() {
        text.push_str("  ");
        if text.chars().count() < 32 {
            text.push_str(&" ".repeat(32 - text.chars().count()));
        }
        let text_length = text.chars().count();
        if let Some(help) = opt.help {
            text.push_str(help);
        }
        if opt.default_help.is_some() || opt.default.is_some() {
            if opt.help.is_some() {
                text.push('\n');
            }
            text.push_str(&" ".repeat(text_length));
            text.push_str("(default: ");
            if let Some(dh) = opt.default_help {
                text.push_str(dh);
            } else if let Some(d) = &opt.default {
                text.push_str(&default_to_str(d));
            }
            text.push(')');
        }
    }
    text
}

fn json_to_choice(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        _ => v.to_string(),
    }
}

fn default_to_str(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        _ => v.to_string(),
    }
}

fn get_help_text(opts: &[OptDef]) -> String {
    let mut all: Vec<OptDef> = opts.to_vec();
    all.push(help_def());
    all.sort_by_key(|o| o.display_index);

    let mut text = String::new();
    text.push_str("\nUsage: jscodeshift [OPTION]... PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... -t URL PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\n");
    text.push_str("Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.\n");
    text.push_str("If --stdin is set, each line of the standard input is used as a path.\n\n");
    text.push_str("Options:\n");
    text.push_str("\"...\" behind an option means that it can be supplied multiple times.\n");
    text.push_str("All options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n");
    let formatted: Vec<String> = all.iter().map(format_option).collect();
    text.push_str(&formatted.join("\n"));
    text.push('\n');
    // trimLeft equivalent: strip a single leading newline.
    if text.starts_with('\n') {
        text.remove(0);
    }
    text
}

fn is_option(value: &str) -> bool {
    value.starts_with('-') && value.len() > 1 && value.starts_with("--") || value.starts_with('-') && value.as_bytes().get(1).map_or(false, |c| *c != b'-')
}

fn is_option_simple(value: &str) -> bool {
    value.starts_with("--") || (value.starts_with('-') && value.len() > 1)
}

#[derive(Debug)]
struct ArgsError {
    exit_code: i32,
    message: String,
}

struct ParsedArgs {
    positional: Vec<Value>,
    options: HashMap<String, Value>,
}

/// Look up an option by its long (`--full`) or short (`-abbr`) token.
fn find_opt<'a>(prepared: &'a [(&'a str, &'a OptDef)], token: &str) -> Option<&'a OptDef> {
    prepared.iter().find(|(k, _)| *k == token).map(|(_, o)| o)
}

fn parse_args(opts: &[OptDef], args: &[String]) -> Result<ParsedArgs, ArgsError> {
    // Build the preparedOptions lookup, including help, --no- forms, abbr.
    let mut all: Vec<OptDef> = opts.to_vec();
    let hd = help_def();
    all.push(hd);
    let mut prepared: Vec<(String, OptDef)> = Vec::new();
    for opt in &all {
        prepared.push((format!("--{}", opt.full), opt.clone()));
        if let Some(abbr) = opt.abbr {
            prepared.push((format!("-{}", abbr), opt.clone()));
        }
        if opt.flag {
            prepared.push((format!("--no-{}", opt.full), opt.clone()));
        }
    }
    let prepared_ref: Vec<(&str, &OptDef)> = prepared
        .iter()
        .map(|(k, o)| (k.as_str(), o))
        .collect();

    let mut options: HashMap<String, Value> = HashMap::new();
    let mut positional: Vec<Value> = Vec::new();

    for opt in &all {
        if let Some(d) = &opt.default {
            options.insert(opt.key.to_string(), d.clone());
        } else if opt.list {
            options.insert(opt.key.to_string(), Value::Array(vec![]));
        }
    }

    let mut missing: Vec<String> = Vec::new();

    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if is_option_simple(arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;
            let opt: OptDef;
            if let Some(eqidx) = arg.find('=') {
                option_name = arg[..eqidx].to_string();
                value = Some(arg[eqidx + 1..].to_string());
            }
            if let Some(found) = find_opt(&prepared_ref, &option_name) {
                opt = found.clone();
            } else {
                // Unknown option: passed along. Replicate argsParser dynamic
                // behavior (flag detection, list promotion, JSON-ish process).
                let real_option_name = strip_option_prefix(&option_name);
                let existing = options.get(&real_option_name);
                let is_list = existing.map_or(false, |v| !is_bool_true(v));
                let next_is_option = i + 1 < args.len() && is_option_simple(&args[i + 1]);
                let flag = existing.is_none() && value.is_none() && next_is_option;
                opt = OptDef {
                    key: Box::leak(real_option_name.clone().into_boxed_str()),
                    full: real_option_name.clone(),
                    abbr: None,
                    flag,
                    list: is_list,
                    default: None,
                    default_help: None,
                    choices: None,
                    help: None,
                    metavar: None,
                    callback: None,
                    process: Some(parse_unknown_value),
                    display_index: 0,
                };
                if is_list {
                    let current = options.get(&real_option_name).cloned();
                    if let Some(cv) = current {
                        if !cv.is_array() {
                            let arr = if is_bool_true(&cv) { vec![] } else { vec![cv] };
                            options.insert(real_option_name.clone(), Value::Array(arr));
                        }
                    }
                }
            }

            if let Some(cb) = opt.callback {
                return Err(ArgsError {
                    exit_code: 0,
                    message: (cb)(),
                });
            } else if opt.flag {
                let v = if option_name.starts_with("--no-") {
                    Value::Bool(false)
                } else if let Some(val) = &value {
                    Value::Bool(val == "1")
                } else {
                    Value::Bool(true)
                };
                options.insert(opt.key.to_string(), v);
            } else {
                let mut consumed = false;
                let mut val = value.clone();
                if val.is_none() && i < args.len() - 1 && !is_option_simple(&args[i + 1]) {
                    val = Some(args[i + 1].clone());
                    i += 1;
                    consumed = true;
                }
                if let Some(v) = val {
                    let processed = if let Some(p) = opt.process {
                        p(&v)
                    } else {
                        Value::String(v)
                    };
                    if opt.list {
                        let arr = options
                            .get_mut(opt.key)
                            .expect("list option initialized");
                        if let Value::Array(a) = arr {
                            a.push(processed);
                        }
                    } else {
                        options.insert(opt.key.to_string(), processed);
                    }
                } else {
                    let _ = consumed;
                    // missingValue marker: remember key, validate at end.
                    missing.push(opt.key.to_string());
                    options.insert(opt.key.to_string(), Value::Null);
                }
            }
        } else {
            // positional argument: numeric strings become numbers.
            if arg.chars().all(|c| c.is_ascii_digit()) && !arg.is_empty() {
                positional.push(json!(arg.parse::<i64>().unwrap_or(0)));
            } else {
                positional.push(Value::String(arg.clone()));
            }
        }
        i += 1;
    }

    if !missing.is_empty() {
        // argsParser reports only the first missing value (throw on first).
        let key = &missing[0];
        let full = all.iter().find(|o| o.key == key).map(|o| o.full.clone()).unwrap_or_default();
        return Err(ArgsError {
            exit_code: 1,
            message: format!(
                "Missing value: --{} requires a value\n\n---\n\n{}",
                full,
                get_help_text(opts)
            ),
        });
    }

    // validateOptions: choices check.
    let mut errors: Vec<String> = Vec::new();
    for opt in &all {
        if let Some(choices) = &opt.choices {
            let val = options.get(opt.key);
            if let Some(v) = val {
                if !choices.iter().any(|c| c == v) {
                    errors.push(format!(
                        "Error: --{} must be one of the values {}",
                        opt.full,
                        choices.iter().map(json_to_choice).collect::<Vec<_>>().join(",")
                    ));
                }
            }
        }
    }
    if !errors.is_empty() {
        return Err(ArgsError {
            exit_code: 1,
            message: format!("{}\n\n---\n\n{}", errors.join("\n"), get_help_text(opts)),
        });
    }

    Ok(ParsedArgs { positional, options })
}

fn is_bool_true(v: &Value) -> bool {
    matches!(v, Value::Bool(true))
}

fn strip_option_prefix(s: &str) -> String {
    // argsParser: optionName.replace(/^--?(no-)?/, '')
    let mut s = s;
    if s.starts_with("--") {
        s = &s[2..];
    } else if s.starts_with('-') {
        s = &s[1..];
    }
    if s.starts_with("no-") {
        s = &s[3..];
    }
    s.to_string()
}

fn parse_unknown_value(v: &str) -> Value {
    // Try JSON parse for compatibility with nomnom, else return raw string.
    serde_json::from_str(v).unwrap_or(Value::String(v.to_string()))
}

// ----------------------------------------------------------------------------
// Ignore rules (mirrors src/ignoreFiles.js)
// ----------------------------------------------------------------------------

struct IgnoreRules {
    globs: Vec<String>,
    set: Option<GlobSet>,
}

impl IgnoreRules {
    fn new() -> Self {
        IgnoreRules {
            globs: Vec::new(),
            set: None,
        }
    }

    fn add_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let pattern = val;
        if !pattern.contains('/') {
            self.globs.push(format!("**/{}", pattern));
        } else if pattern.ends_with('/') {
            self.globs.push(format!("**/{}**", pattern));
            self.globs.push(format!("{}**", pattern));
        }
        self.globs.push(pattern.to_string());
    }

    fn add_input(&mut self, input: Option<&Value>) {
        if let Some(v) = input {
            let patterns: Vec<String> = match v {
                Value::String(s) => vec![s.clone()],
                Value::Array(a) => a
                    .iter()
                    .filter_map(|x| x.as_str().map(String::from))
                    .collect(),
                _ => vec![],
            };
            for p in patterns {
                self.add_pattern(&p);
            }
        }
    }

    fn add_from_file(&mut self, input: Option<&Value>) {
        if let Some(v) = input {
            let files: Vec<String> = match v {
                Value::String(s) => vec![s.clone()],
                Value::Array(a) => a
                    .iter()
                    .filter_map(|x| x.as_str().map(String::from))
                    .collect(),
                _ => vec![],
            };
            let mut lines: Vec<String> = Vec::new();
            for config in &files {
                if let Ok(metadata) = std::fs::metadata(config) {
                    if metadata.is_file() {
                        if let Ok(content) = std::fs::read_to_string(config) {
                            for line in content.split('\n') {
                                lines.push(line.to_string());
                            }
                        }
                    }
                }
            }
            for l in lines {
                self.add_pattern(&l);
            }
        }
    }

    fn build(&mut self) {
        if self.globs.is_empty() {
            self.set = None;
            return;
        }
        let mut builder = GlobSetBuilder::new();
        for g in &self.globs {
            if let Ok(glob) = Glob::new(g) {
                let _ = builder.add(glob.compile_matcher());
            }
        }
        self.set = builder.build().ok();
    }

    fn should_ignore(&self, path: &str) -> bool {
        match &self.set {
            None => false,
            Some(set) => {
                if set.is_match(path) {
                    return true;
                }
                let normalized = strip_leading_traversal(path);
                if normalized != path && set.is_match(&normalized) {
                    return true;
                }
                false
            }
        }
    }
}

fn strip_leading_traversal(path: &str) -> String {
    // /^(?:\.\.?[/\\])+/  -- repeatedly strip ./ or ../ (with separator).
    let bytes = path.as_bytes();
    let mut i = 0;
    while i + 1 < bytes.len() {
        if bytes[i] == b'.'
            && (bytes[i + 1] == b'/' || bytes[i + 1] == b'\\')
        {
            i += 2;
        } else if i + 2 < bytes.len()
            && bytes[i] == b'.'
            && bytes[i + 1] == b'.'
            && (bytes[i + 2] == b'/' || bytes[i + 2] == b'\\')
        {
            i += 3;
        } else {
            break;
        }
    }
    path[i..].to_string()
}

// ----------------------------------------------------------------------------
// File discovery (mirrors Runner.js getAllFiles / dirFiles)
// ----------------------------------------------------------------------------

fn collect_dir_files(dir: &Path, files: &mut Vec<String>, ignores: &IgnoreRules) {
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return, // mirror: "this should not happen"; bail silently.
    };
    for entry in entries.flatten() {
        let name = entry.path();
        let name_str = name.to_string_lossy().into_owned();
        match std::fs::symlink_metadata(&name) {
            Ok(_stat) => {
                if ignores.should_ignore(&name_str) {
                    // ignore
                } else if std::fs::metadata(&name).map(|m| m.is_dir()).unwrap_or(false) {
                    let mut child = name.clone();
                    child.push("");
                    collect_dir_files(&child, files, ignores);
                } else {
                    files.push(name_str);
                }
            }
            Err(_) => {
                // symlink issue: original prints "Skipping path ... which does not exist." to stdout.
                let mut out = io::stdout().lock();
                let _ = writeln!(out, "Skipping path \"{}\" which does not exist.", name_str);
            }
        }
    }
}

fn get_all_files(paths: &[String], filter: &dyn Fn(&str) -> bool, ignores: &IgnoreRules) -> Vec<String> {
    let mut all = Vec::new();
    for file in paths {
        match std::fs::symlink_metadata(file) {
            Err(_) => {
                let mut err = io::stderr().lock();
                let _ = writeln!(err, "Skipping path {} which does not exist. ", file);
            }
            Ok(stat) => {
                if stat.is_dir() {
                    let mut dir_files = Vec::new();
                    collect_dir_files(Path::new(file), &mut dir_files, ignores);
                    for f in dir_files {
                        if filter(&f) {
                            all.push(f);
                        }
                    }
                } else if !filter(file) || ignores.should_ignore(file) {
                    // ignoring the file
                } else {
                    all.push(file.clone());
                }
            }
        }
    }
    all
}

// ----------------------------------------------------------------------------
// Runner / worker orchestration
// ----------------------------------------------------------------------------

struct Counters {
    error: u64,
    ok: u64,
    nochange: u64,
    skip: u64,
    stats: HashMap<String, u64>,
}

fn available_cpus() -> usize {
    std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1)
        .saturating_sub(1)
        .max(1)
}

/// Write with backpressure handling equivalent to the original bufferedWrite:
/// if stdout would block / fails, keep going (best-effort). In practice stdout
/// is a pipe/file and writes succeed; we keep the behavior simple and reliable.
fn write_stdout(msg: &str) {
    let mut out = io::stdout().lock();
    let _ = out.write_all(msg.as_bytes());
    let _ = out.flush();
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{}\n", s)
    }
}

/// Spawn one Node bridge worker, returning its handle (child, bridge fd, reader).
struct Worker {
    child: process::Child,
    bridge_write: std::fs::File,
    reader: BufReader<std::fs::File>,
}

fn spawn_worker(bridge_path: &str, transform_file: &str, babel: bool) -> io::Result<Worker> {
    use nix::sys::socket::{socketpair, AddressFamily, SockFlag, SockType};

    let (parent, child) = socketpair(
        AddressFamily::Unix,
        SockType::Stream,
        None,
        SockFlag::empty(),
    )
    .map_err(|e| io::Error::from_raw_os_error(e as i32))?;

    // Let the child inherit the socket end and stdin/stdout/stderr.
    use nix::fcntl::{FcntlArg, FdFlag, OFlag};
    use std::os::unix::io::RawFd;
    let _ = nix::fcntl::fcntl(parent.as_raw_fd(), FcntlArg::F_SETFD(FdFlag::empty()));
    let _ = nix::fcntl::fcntl(parent.as_raw_fd(), FcntlArg::F_SETFL(OFlag::O_NONBLOCK.negate()));
    let child_fd: RawFd = child.as_raw_fd();

    let mut cmd = Command::new("node");
    cmd.arg(bridge_path);
    cmd.arg(child_fd.to_string());
    cmd.arg("_"); // placeholder matching argv[4] in the bridge
    cmd.arg(transform_file);
    cmd.arg(if babel { "babel" } else { "no-babel" });
    cmd.stdin(Stdio::inherit());
    cmd.stdout(Stdio::inherit());
    cmd.stderr(Stdio::inherit());

    // Mark child fd to be kept across exec (do NOT set CLOEXEC).
    use nix::fcntl::FcntlArg;
    let _ = nix::fcntl::fcntl(child_fd, FcntlArg::F_SETFD(FdFlag::empty()));

    let mut child = cmd.spawn()?;

    // We must keep the child socket end open in our process until exec; after
    // spawn the child has its copy. Close our view of `child` to avoid keeping
    // a second open end (which would prevent EOF detection). We keep `parent`.
    drop(child);

    // parent fd becomes our read+write end.
    let parent_file = unsafe { std::fs::File::from_raw_fd(parent.as_raw_fd()) };
    std::mem::forget(parent); // avoid double close; File owns it now
    let parent_read = unsafe { std::fs::File::from_raw_fd(parent.as_raw_fd()) };

    let parent_write = parent_file.try_clone()?;

    Ok(Worker {
        child,
        bridge_write: parent_write,
        reader: BufReader::new(parent_read),
    })
}","path":"/workspace/src/main.rs"}

