{"command":"create","file_text":"#!/usr/bin/env node
/**
 * Transform execution bridge for the Rust jscodeshift CLI.
 *
 * This is the minimal JavaScript bridge retained to load and execute user
 * transforms against the original jscodeshift core API (recast, collections,
 * templates, builders, node matching, parser adapters). The Rust process owns
 * all orchestration (arg parsing, file discovery, ignore rules, runner,
 * workers, progress output, file stats, exit codes); this bridge owns only the
 * in-process transform execution previously performed by src/Worker.js.
 *
 * Communication protocol (newline-delimited JSON over two pipe file
 * descriptors passed as argv):
 *
 *   parent -> bridge (read fd, argv[2]):
 *     {"files":[...], "options":{...}}   a chunk of files to transform
 *
 *   bridge -> parent (write fd, argv[3]):
 *     {"action":"status","status":"ok|nochange|skip|error","msg":"..."}
 *     {"action":"update","name":"...","quantity":N}
 *     {"action":"free"}
 *     {"action":"report","file":"...","msg":"..."}
 *
 * When the parent closes its write end (EOF on the read fd), the bridge exits.
 * stdout and stderr are inherited so that transform `print` output and any
 * stray logging behave exactly as the original worker process.
 */
'use strict';

const fs = require('graceful-fs');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');
const getParser = require('../codebase/src/getParser');
const jscodeshift = require('../codebase/src/core');

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

let parserFromTransform;
let transform;

const readFd = parseInt(process.argv[2], 10);
const writeFd = parseInt(process.argv[3], 10);
const outStream = fs.createWriteStream('', { fd: writeFd });

function send(obj) {
  outStream.write(JSON.stringify(obj) + '\n');
}

function prepareJscodeshift(options) {
  const parser =
    parserFromTransform || getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([presetEnv.default, { targets: { node: true } }]);
    }
    presets.push(
      /\.tsx?$/.test(tr)
        ? require('@babel/preset-typescript').default
        : require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const module = require(tr);
  transform =
    typeof module.default === 'function' ? module.default : module;
  if (module.parser) {
    parserFromTransform =
      typeof module.parser === 'string' ? getParser(module.parser) : module.parser;
  }
}

function free() {
  send({ action: 'free' });
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  send({ action: 'status', status: status, msg: msg });
}

function report(file, msg) {
  send({ action: 'report', file, msg });
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  send({ action: 'update', name: name, quantity: quantity });
}

function trimStackTrace(trace) {
  if (!trace) {
    return '';
  }
  const lines = trace.split('\n');
  const result = [];
  lines.every(function (line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function run(data) {
  const files = data.files;
  const options = data.options || {};
  if (!files.length) {
    free();
    return;
  }
  // Process files serially within a chunk, mirroring the per-chunk ordering of
  // the original neo-async `each` (status messages are emitted in file order).
  (async function () {
    for (const file of files) {
      await new Promise(function (resolve) {
        fs.readFile(file, async function (err, source) {
          if (err) {
            updateStatus('error', file, 'File error: ' + err);
            resolve();
            return;
          }
          source = source.toString();
          try {
            const jsc = prepareJscodeshift(options);
            const out = await transform(
              { path: file, source: source },
              {
                j: jsc,
                jscodeshift: jsc,
                stats: options.dry ? stats : empty,
                report: (msg) => report(file, msg),
              },
              options
            );
            if (!out || out === source) {
              updateStatus(out ? 'nochange' : 'skip', file);
              resolve();
              return;
            }
            if (options.print) {
              console.log(out); // eslint-disable-line no-console
            }
            if (!options.dry) {
              writeFileAtomic(file, out, function (e) {
                if (e) {
                  updateStatus('error', file, 'File writer error: ' + e);
                } else {
                  updateStatus('ok', file);
                }
                resolve();
              });
            } else {
              updateStatus('ok', file);
              resolve();
            }
          } catch (err) {
            updateStatus(
              'error',
              file,
              'Transformation error (' +
                err.message.replace(/\n/g, ' ') +
                ')\n' +
                trimStackTrace(err.stack)
            );
            resolve();
          }
        });
      });
    }
    free();
  })().catch(function () {
    free();
  });
}

// argv: [node, script, readFd, writeFd, transformFile, babel|no-babel]
setup(process.argv[4], process.argv[5]);

const inStream = fs.createReadStream('', { fd: readFd });
inStream.setEncoding('utf8');
let inBuffer = '';
inStream.on('data', function (chunk) {
  let idx;
  inBuffer += chunk;
  while ((idx = inBuffer.indexOf('\n')) !== -1) {
    const line = inBuffer.slice(0, idx);
    inBuffer = inBuffer.slice(idx + 1);
    if (line.length === 0) continue;
    try {
      run(JSON.parse(line));
    } catch (_) {
      // ignore malformed lines
    }
  }
});
inStream.on('end', function () {
  // Give any pending writes a chance to flush, then exit.
  outStream.end(function () {
    process.exit(0);
  });
});
inStream.on('error', function () {
  process.exit(0);
});","path":"/workspace/bridge/transform-host.js"}

{"command":"create","file_text":"// ANSI color helpers replicating the exact escape sequences produced by the
// `picocolors` package (forced-color / TTY mode) that the original Runner.js
// relies on. picocolors uses the default foreground (`\x1b[39m`) to reset text
// color and `\x1b[49m` to reset background, matching the observed output.

pub struct Colors;

impl Colors {
    pub fn enabled() -> bool {
        // The original CLI relies on picocolors, which only emits colors when
        // the output is a TTY (or FORCE_COLOR is set). To preserve the exact
        // plain-text behavior of the original when piped, we honor the same
        // detection: colors are on only for an interactive stdout or an
        // explicit FORCE_COLOR request.
        if std::env::var_os("FORCE_COLOR").is_some() {
            return true;
        }
        is_stdout_tty()
    }

    pub fn green(s: &str) -> String {
        if Self::enabled() {
            format!("\x1b[32m{}\x1b[39m", s)
        } else {
            s.to_string()
        }
    }
    pub fn red(s: &str) -> String {
        if Self::enabled() {
            format!("\x1b[31m{}\x1b[39m", s)
        } else {
            s.to_string()
        }
    }
    pub fn yellow(s: &str) -> String {
        if Self::enabled() {
            format!("\x1b[33m{}\x1b[39m", s)
        } else {
            s.to_string()
        }
    }
    pub fn blue(s: &str) -> String {
        if Self::enabled() {
            format!("\x1b[34m{}\x1b[39m", s)
        } else {
            s.to_string()
        }
    }
    pub fn bg_green(s: &str) -> String {
        if Self::enabled() {
            format!("\x1b[42m{}\x1b[49m", s)
        } else {
            s.to_string()
        }
    }
    pub fn bg_yellow(s: &str) -> String {
        if Self::enabled() {
            format!("\x1b[43m{}\x1b[49m", s)
        } else {
            s.to_string()
        }
    }
    pub fn bg_red(s: &str) -> String {
        if Self::enabled() {
            format!("\x1b[41m{}\x1b[49m", s)
        } else {
            s.to_string()
        }
    }
    pub fn bg_blue(s: &str) -> String {
        if Self::enabled() {
            format!("\x1b[44m{}\x1b[49m", s)
        } else {
            s.to_string()
        }
    }
    pub fn white(s: &str) -> String {
        if Self::enabled() {
            format!("\x1b[37m{}\x1b[39m", s)
        } else {
            s.to_string()
        }
    }
}

fn is_stdout_tty() -> bool {
    // SAFETY: isatty simply queries the terminal status of an fd.
    unsafe { libc::isatty(libc::STDOUT_FILENO) != 0 }
}","path":"/workspace/src/color.rs"}

{"command":"create","file_text":"// jscodeshift CLI, migrated to Rust.
//
// This binary owns all orchestration previously performed by bin/jscodeshift.js,
// src/argsParser.js, src/Runner.js and src/ignoreFiles.js: argument parsing,
// help/version output, error reporting, file discovery, ignore rules, runner
// orchestration, worker spawning, progress output, file stats and exit codes.
//
// Transform execution (loading a transform module, running it against file
// source via the original jscodeshift core API) is delegated to the retained
// JavaScript bridge `bridge/transform-host.js`. Each worker is a Node process
// running that bridge, communicated with over two pipes using newline-delimited
// JSON, mirroring the child_process.fork + IPC message protocol of the original
// src/Worker.js (parent->child messages carry file chunks + options; the bridge
// reports status/update/free/report messages back).

use std::collections::HashMap;
use std::ffi::CString;
use std::io::{self, BufRead, BufReader, Write};
use std::os::unix::io::FromRawFd;
use std::path::Path;
use std::process::{self, Command, Stdio};
use std::time::Instant;

use globset::{Glob, GlobSet, GlobSetBuilder};
use serde_json::{json, Value};

mod color;
use color::Colors;

const CHUNK_SIZE: usize = 50;

// ----------------------------------------------------------------------------
// CLI option definitions (mirror bin/jscodeshift.js + argsParser prepareOptions)
// ----------------------------------------------------------------------------

#[derive(Clone)]
struct OptDef {
    key: String,
    full: String,
    abbr: Option<char>,
    flag: bool,
    list: bool,
    default: Option<Value>,
    default_help: Option<&'static str>,
    choices: Option<Vec<Value>>,
    help: Option<&'static str>,
    metavar: Option<&'static str>,
    callback: Option<fn() -> String>,
    process: Option<fn(&str) -> Value>,
    display_index: u32,
}

fn option_defs() -> Vec<OptDef> {
    let mk = |key: &'static str,
              full: &'static str,
              abbr: Option<char>,
              flag: bool,
              list: bool,
              default: Option<Value>,
              default_help: Option<&'static str>,
              choices: Option<Vec<Value>>,
              help: Option<&'static str>,
              metavar: Option<&'static str>,
              callback: Option<fn() -> String>,
              process: Option<fn(&str) -> Value>,
              display_index: u32| OptDef {
        key: key.to_string(),
        full: full.to_string(),
        abbr,
        flag,
        list,
        default,
        default_help,
        choices,
        help,
        metavar,
        callback,
        process,
        display_index,
    };

    vec![
        mk("transform", "transform", Some('t'), false, false,
