fn version_cb() -> String {
    version_string()
}

fn help_def() -> OptDef {
    OptDef {
        key: "help".to_string(),
        full: "help".to_string(),
        abbr: Some('h'),
        flag: false,
        list: false,
        default: None,
        default_help: None,
        choices: None,
        help: Some("print this help and exit"),
        metavar: None,
        callback: None,
        process: None,
        display_index: 5,
    }
}

fn parse_number(v: &str) -> Value {
    // argsParser uses `process: Number`. For valid integers we emit a JSON
    // number; non-numeric input yields NaN which, as JSON, becomes null and
    // later fails the choices check (mirroring the original behavior).
    if let Ok(n) = v.parse::<i64>() {
        json!(n)
    } else if let Ok(n) = v.parse::<f64>() {
        if n.is_finite() {
            json!(n)
        } else {
            Value::Null
        }
    } else {
        Value::Null
    }
}

fn parse_parser_config(v: &str) -> Value {
    match std::fs::read_to_string(v) {
        Ok(contents) => serde_json::from_str(&contents).unwrap_or(Value::Null),
        Err(_) => Value::Null,
    }
}

fn version_string() -> String {
    [
        "jscodeshift: 17.4.0",
        " - babel: 7.29.6",
        " - babylon: 7.29.7",
        " - flow: 0.237.2",
        " - recast: 0.23.11\n",
    ]
    .join("\n")
}

fn json_to_choice(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        _ => v.to_string(),
    }
}

fn default_to_str(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        _ => v.to_string(),
    }
}

fn format_option(opt: &OptDef) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = opt.abbr {
        text.push_str(&format!("-{}, ", abbr));
    } else {
        text.push_str("    ");
    }
    text.push_str("--");
    if opt.flag {
        text.push_str("(no-)");
    }
    text.push_str(&opt.full);
    if let Some(choices) = &opt.choices {
        text.push('=');
        text.push_str(&choices.iter().map(json_to_choice).collect::<Vec<_>>().join("|"));
    } else if let Some(mv) = opt.metavar {
        text.push('=');
        text.push_str(mv);
    }
    if opt.list {
        text.push_str(" ...");
    }
    if opt.default_help.is_some() || opt.default.is_some() || opt.help.is_some() {
        text.push_str("  ");
        let len = text.chars().count();
        if len < 32 {
            text.push_str(&" ".repeat(32 - len));
        }
        let text_length = text.chars().count();
        if let Some(help) = opt.help {
            text.push_str(help);
        }
        if opt.default_help.is_some() || opt.default.is_some() {
            if opt.help.is_some() {
                text.push('\n');
            }
            text.push_str(&" ".repeat(text_length));
            text.push_str("(default: ");
            if let Some(dh) = opt.default_help {
                text.push_str(dh);
            } else if let Some(d) = &opt.default {
                text.push_str(&default_to_str(d));
            }
            text.push(')');
        }
    }
    text
}

fn get_help_text(opts: &[OptDef]) -> String {
    let mut all: Vec<OptDef> = opts.to_vec();
    all.push(help_def());
    all.sort_by_key(|o| o.display_index);

    let mut text = String::new();
    text.push_str("\nUsage: jscodeshift [OPTION]... PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... -t URL PATH...\n");
    text.push_str("  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\n");
    text.push_str("Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.\n");
    text.push_str("If --stdin is set, each line of the standard input is used as a path.\n\n");
    text.push_str("Options:\n");
    text.push_str("\"...\" behind an option means that it can be supplied multiple times.\n");
    text.push_str("All options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n");
    let formatted: Vec<String> = all.iter().map(format_option).collect();
    text.push_str(&formatted.join("\n"));
    text.push('\n');
    // trimLeft equivalent: strip a single leading newline.
    if text.starts_with('\n') {
        text.remove(0);
    }
    text
}

fn is_option_simple(value: &str) -> bool {
    // /^--?/  -- a leading dash followed by at least one more character.
    value.starts_with('-') && value.len() > 1
}

#[derive(Debug)]
struct ArgsError {
    exit_code: i32,
    message: String,
}

struct ParsedArgs {
    positional: Vec<Value>,
    options: HashMap<String, Value>,
}

fn find_opt<'a>(prepared: &'a [(String, OptDef)], token: &str) -> Option<&'a OptDef> {
    prepared.iter().find(|(k, _)| k == token).map(|(_, o)| o)
}

fn is_bool_true(v: &Value) -> bool {
    matches!(v, Value::Bool(true))
}

fn strip_option_prefix(s: &str) -> String {
    // argsParser: optionName.replace(/^--?(no-)?/, '')
    let mut s = s;
    if s.starts_with("--") {
        s = &s[2..];
    } else if s.starts_with('-') {
        s = &s[1..];
    }
    if s.starts_with("no-") {
        s = &s[3..];
    }
    s.to_string()
}

fn parse_unknown_value(v: &str) -> Value {
    serde_json::from_str(v).unwrap_or(Value::String(v.to_string()))
}

fn parse_args(opts: &[OptDef], args: &[String]) -> Result<ParsedArgs, ArgsError> {
    let mut all: Vec<OptDef> = opts.to_vec();
    all.push(help_def());

    // Build preparedOptions lookup: --full, -abbr, --no-full (for flags).
    let mut prepared: Vec<(String, OptDef)> = Vec::new();
    for opt in &all {
        prepared.push((format!("--{}", opt.full), opt.clone()));
        if let Some(abbr) = opt.abbr {
            prepared.push((format!("-{}", abbr), opt.clone()));
        }
        if opt.flag {
            prepared.push((format!("--no-{}", opt.full), opt.clone()));
        }
    }

    let mut options: HashMap<String, Value> = HashMap::new();
    for opt in &all {
        if let Some(d) = &opt.default {
            options.insert(opt.key.clone(), d.clone());
        } else if opt.list {
            options.insert(opt.key.clone(), Value::Array(vec![]));
        }
    }

    let mut missing: Vec<String> = Vec::new();
    let mut positional: Vec<Value> = Vec::new();

    let mut i = 0usize;
    while i < args.len() {
        let arg = args[i].clone();
        if is_option_simple(&arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;
            if let Some(eqidx) = arg.find('=') {
                option_name = arg[..eqidx].to_string();
                value = Some(arg[eqidx + 1..].to_string());
            }

            let opt: OptDef;
            if let Some(found) = find_opt(&prepared, &option_name) {
                opt = found.clone();
            } else {
                // Unknown option: passed along (argsParser dynamic branch).
                let real_option_name = strip_option_prefix(&option_name);
                let existing = options.get(&real_option_name);
                let is_list = existing.map_or(false, |v| !is_bool_true(v));
                let next_is_option = i + 1 < args.len() && is_option_simple(&args[i + 1]);
                let flag = existing.is_none() && value.is_none() && next_is_option;
                opt = OptDef {
                    key: real_option_name.clone(),
                    full: real_option_name.clone(),
                    abbr: None,
                    flag,
                    list: is_list,
                    default: None,
                    default_help: None,
                    choices: None,
                    help: None,
                    metavar: None,
                    callback: None,
                    process: Some(parse_unknown_value),
                    display_index: 0,
                };
                if is_list {
                    if let Some(cv) = options.get(&real_option_name).cloned() {
                        if !cv.is_array() {
                            let arr = if is_bool_true(&cv) { vec![] } else { vec![cv] };
                            options.insert(real_option_name.clone(), Value::Array(arr));
                        }
                    }
                }
            }

            if let Some(cb) = opt.callback {
                return Err(ArgsError {
                    exit_code: 0,
                    message: (cb)(),
                });
            } else if opt.flag {
                let v = if option_name.starts_with("--no-") {
                    Value::Bool(false)
                } else if let Some(val) = &value {
                    Value::Bool(val == "1")
                } else {
                    Value::Bool(true)
                };
                options.insert(opt.key.clone(), v);
            } else {
                let mut val = value.clone();
                if val.is_none() && i < args.len() - 1 && !is_option_simple(&args[i + 1]) {
                    val = Some(args[i + 1].clone());
                    i += 1;
                }
                if let Some(v) = val {
                    let processed = if let Some(p) = opt.process {
                        p(&v)
                    } else {
                        Value::String(v)
                    };
                    if opt.list {
                        if let Some(Value::Array(a)) = options.get_mut(&opt.key) {
                            a.push(processed);
                        }
                    } else {
                        options.insert(opt.key.clone(), processed);
                    }
                } else {
                    missing.push(opt.key.clone());
                    options.insert(opt.key.clone(), Value::Null);
                }
            }
        } else {
            // positional: /^\d+$/ -> Number(arg)
            if !arg.is_empty() && arg.chars().all(|c| c.is_ascii_digit()) {
                positional.push(json!(arg.parse::<i64>().unwrap_or(0)));
            } else {
                positional.push(Value::String(arg));
            }
        }
        i += 1;
    }

    if !missing.is_empty() {
        let key = &missing[0];
        let full = all
            .iter()
            .find(|o| &o.key == key)
            .map(|o| o.full.clone())
            .unwrap_or_default();
        return Err(ArgsError {
            exit_code: 1,
            message: format!(
                "Missing value: --{} requires a value\n\n---\n\n{}",
                full,
                get_help_text(opts)
            ),
        });
    }

    // validateOptions: choices.
    let mut errors: Vec<String> = Vec::new();
    for opt in &all {
        if let Some(choices) = &opt.choices {
            if let Some(v) = options.get(&opt.key) {
                if !choices.iter().any(|c| c == v) {
                    errors.push(format!(
                        "Error: --{} must be one of the values {}",
                        opt.full,
                        choices.iter().map(json_to_choice).collect::<Vec<_>>().join(",")
                    ));
                }
            }
        }
    }
    if !errors.is_empty() {
        return Err(ArgsError {
            exit_code: 1,
            message: format!("{}\n\n---\n\n{}", errors.join("\n"), get_help_text(opts)),
        });
    }

    Ok(ParsedArgs { positional, options })
}

// ----------------------------------------------------------------------------
// Ignore rules (mirror src/ignoreFiles.js)
// ----------------------------------------------------------------------------

struct IgnoreRules {
    globs: Vec<String>,
    set: Option<GlobSet>,
}

impl IgnoreRules {
    fn new() -> Self {
        IgnoreRules { globs: Vec::new(), set: None }
    }

    fn add_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        if !val.contains('/') {
            self.globs.push(format!("**/{}", val));
        } else if val.ends_with('/') {
            self.globs.push(format!("**/{}**", val));
            self.globs.push(format!("{}**", val));
        }
        self.globs.push(val.to_string());
    }

    fn add_input(&mut self, input: Option<&Value>) {
        let patterns: Vec<String> = match input {
            Some(Value::String(s)) => vec![s.clone()],
            Some(Value::Array(a)) => a.iter().filter_map(|x| x.as_str().map(String::from)).collect(),
            _ => vec![],
        };
        for p in patterns {
            self.add_pattern(&p);
        }
    }

    fn add_from_file(&mut self, input: Option<&Value>) {
        let files: Vec<String> = match input {
            Some(Value::String(s)) => vec![s.clone()],
            Some(Value::Array(a)) => a.iter().filter_map(|x| x.as_str().map(String::from)).collect(),
            _ => vec![],
        };
        let mut lines: Vec<String> = Vec::new();
        for config in &files {
            if let Ok(metadata) = std::fs::metadata(config) {
                if metadata.is_file() {
                    if let Ok(content) = std::fs::read_to_string(config) {
                        for line in content.split('\n') {
                            lines.push(line.to_string());
                        }
                    }
                }
            }
        }
        for l in lines {
            self.add_pattern(&l);
        }
    }

    fn build(&mut self) {
        if self.globs.is_empty() {
            self.set = None;
            return;
        }
        let mut builder = GlobSetBuilder::new();
        for g in &self.globs {
            if let Ok(glob) = Glob::new(g) {
                let _ = builder.add(glob.compile_matcher());
            }
        }
        self.set = builder.build().ok();
    }

    fn should_ignore(&self, path: &str) -> bool {
        match &self.set {
            None => false,
            Some(set) => {
                if set.is_match(path) {
                    return true;
                }
                let normalized = strip_leading_traversal(path);
                if normalized != path && set.is_match(&normalized) {
                    return true;
                }
                false
            }
        }
    }
}

fn strip_leading_traversal(path: &str) -> String {
    // /^(?:\.\.?[/\\])+/  -- strip leading ./ or ../ (with separator).
    let bytes = path.as_bytes();
    let mut i = 0;
    loop {
        if i + 1 < bytes.len() && bytes[i] == b'.' && (bytes[i + 1] == b'/' || bytes[i + 1] == b'\\') {
            i += 2;
        } else if i + 2 < bytes.len() && bytes[i] == b'.' && bytes[i + 1] == b'.'
            && (bytes[i + 2] == b'/' || bytes[i + 2] == b'\\')
        {
            i += 3;
        } else {
            break;
        }
    }
    path[i..].to_string()
}

// ----------------------------------------------------------------------------
// File discovery (mirror Runner.js getAllFiles / dirFiles)
// ----------------------------------------------------------------------------

fn collect_dir_files(dir: &Path, files: &mut Vec<String>, ignores: &IgnoreRules) {
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for entry in entries.flatten() {
        let name = entry.path();
        let name_str = name.to_string_lossy().into_owned();
        match std::fs::symlink_metadata(&name) {
            Ok(_meta) => {
                if ignores.should_ignore(&name_str) {
                    // ignore
                } else if std::fs::metadata(&name).map(|m| m.is_dir()).unwrap_or(false) {
                    let mut child = name.clone();
                    child.push("");
                    collect_dir_files(&child, files, ignores);
                } else {
                    files.push(name_str);
                }
            }
            Err(_) => {
                let mut out = io::stdout().lock();
                let _ = writeln!(out, "Skipping path \"{}\" which does not exist.", name_str);
            }
        }
    }
}

fn get_all_files(
    paths: &[String],
    filter: &dyn Fn(&str) -> bool,
    ignores: &IgnoreRules,
) -> Vec<String> {
    let mut all = Vec::new();
    for file in paths {
        match std::fs::symlink_metadata(file) {
            Err(_) => {
                let mut err = io::stderr().lock();
                let _ = writeln!(err, "Skipping path {} which does not exist. ", file);
            }
            Ok(stat) => {
                if stat.is_dir() {
                    let mut dir_files = Vec::new();
                    collect_dir_files(Path::new(file), &mut dir_files, ignores);
                    for f in dir_files {
                        if filter(&f) {
                            all.push(f);
                        }
                    }
                } else if !filter(file) || ignores.should_ignore(file) {
                    // ignoring the file
                } else {
                    all.push(file.clone());
                }
            }
        }
    }
    all
}

// ----------------------------------------------------------------------------
// Worker (Node bridge) orchestration
// ----------------------------------------------------------------------------

struct Worker {
    child: process::Child,
    bridge_write: std::fs::File,
    reader: BufReader<std::fs::File>,
}

/// Create a unidirectional pipe, returning (read_fd, write_fd).
fn make_pipe() -> io::Result<(i32, i32)> {
    let mut fds = [0i32; 2];
    // SAFETY: pipe() fills fds with two valid descriptors on success.
    let rc = unsafe { libc::pipe(fds.as_mut_ptr()) };
    if rc != 0 {
        return Err(io::Error::last_os_error());
    }
    Ok((fds[0], fds[1]))
}

fn spawn_worker(bridge_path: &str, transform_file: &str, babel: bool) -> io::Result<Worker> {
    // Two pipes: parent_write -> child_read (work), child_write -> parent_read (results).
    let (cr, pw) = make_pipe()?;
    let (pr, cw) = make_pipe()?;

    let cr_s = cr.to_string();
    let cw_s = cw.to_string();

    let mut cmd = Command::new("node");
    cmd.arg(bridge_path);
    cmd.arg(&cr_s); // read fd (parent -> child)
    cmd.arg(&cw_s); // write fd (child -> parent)
    cmd.arg(transform_file);
    cmd.arg(if babel { "babel" } else { "no-babel" });
    cmd.stdin(Stdio::inherit());
    cmd.stdout(Stdio::inherit());
    cmd.stderr(Stdio::inherit());

    // Make the child ends inheritable across exec (clear FD_CLOEXEC).
    let _ = unsafe { libc::fcntl(cr, libc::F_SETFD, 0) };
    let _ = unsafe { libc::fcntl(cw, libc::F_SETFD, 0) };

    let child = cmd.spawn()?;

    // Parent closes its copy of the child ends so that EOF propagates correctly.
    unsafe { libc::close(cr) };
    unsafe { libc::close(cw) };

    // Keep parent ends open; wrap them in Files. Use FromRawFd; ownership is
    // transferred to the File (it will close on drop).
    let bridge_write = unsafe { std::fs::File::from_raw_fd(pw) };
    let parent_read = unsafe { std::fs::File::from_raw_fd(pr) };

    Ok(Worker {
        child,
        bridge_write,
        reader: BufReader::new(parent_read),
    })
}

impl Worker {
    fn send(&mut self, msg: &Value) -> io::Result<()> {
        let mut line = serde_json::to_string(msg).unwrap_or_default();
        line.push('\n');
        self.bridge_write.write_all(line.as_bytes())
    }
}

// ----------------------------------------------------------------------------
// Runner
// ----------------------------------------------------------------------------

struct Counters {
    error: u64,
    ok: u64,
    nochange: u64,
    skip: u64,
    stats: HashMap<String, u64>,
}

fn available_cpus() -> usize {
    std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1)
        .saturating_sub(1)
        .max(1)
}

fn write_stdout(msg: &str) {
    let mut out = io::stdout().lock();
    let _ = out.write_all(msg.as_bytes());
    let _ = out.flush();
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{}\n", s)
    }
}

fn log_status(status: &str, msg: &str, verbose: u64) {
    let lb = line_break(msg);
    match status {
        "ok" => {
            if verbose >= 2 {
                write_stdout(&format!("{}{}", Colors::bg_green(&Colors::white(" OKK ")), lb));
            }
        }
        "nochange" => {
            if verbose >= 1 {
                write_stdout(&format!("{}{}", Colors::bg_yellow(&Colors::white(" NOC ")), lb));
            }
        }
        "skip" => {
            if verbose >= 1 {
                write_stdout(&format!("{}{}", Colors::bg_yellow(&Colors::white(" SKIP ")), lb));
            }
        }
        "error" => {
            if verbose >= 0 {
                write_stdout(&format!("{}{}", Colors::bg_red(&Colors::white(" ERR ")), lb));
            }
        }
        _ => {}
    }
}

fn report(file: &str, msg: &str) {
    let out = format!("{}{} {}\n", Colors::bg_blue(&Colors::white(" REP ")), file, msg);
    write_stdout(&out);
}

fn show_file_stats(c: &Counters) {
    let mut out = String::new();
    out.push_str("Results: \n");
    out.push_str(&Colors::red(&format!("{} errors\n", c.error)));
    out.push_str(&Colors::yellow(&format!("{} unmodified\n", c.nochange)));
    out.push_str(&Colors::yellow(&format!("{} skipped\n", c.skip)));
    out.push_str(&Colors::green(&format!("{} ok\n", c.ok)));
    write_stdout(&out);
}

fn show_stats(stats: &HashMap<String, u64>) {
    let mut names: Vec<&String> = stats.keys().collect();
    names.sort();
    if !names.is_empty() {
        write_stdout(&Colors::blue("Stats: \n"));
    }
    let mut out = String::new();
    for name in names {
        out.push_str(&format!("{}: {}\n", name, stats[name]));
    }
    write_stdout(&out);
}

fn opts_to_bridge(options: &HashMap<String, Value>) -> Value {
    // Only the options Worker.js actually reads are forwarded, plus all options
    // are passed to the transformer (so forward everything that is JSON-able).
    let mut obj = serde_json::Map::new();
    for (k, v) in options {
        obj.insert(k.clone(), v.clone());
    }
    Value::Object(obj)
}

fn run_transform(
    transform_file: &str,
    paths: &[String],
    options: &HashMap<String, Value>,
) {
    let cpus_opt = options.get("cpus").and_then(|v| v.as_i64());
    let available = available_cpus();
    let cpus = match cpus_opt {
        Some(n) if n > 0 => (available as i64).min(n) as usize,
        _ => available,
    };

    let extensions: Option<Vec<String>> = options
        .get("extensions")
        .and_then(|v| v.as_str())
        .map(|s| {
            s.split(',')
                .map(|e| format!(".{}", e))
                .collect::<Vec<_>>()
        });

    let filter = |name: &str| -> bool {
        match &extensions {
            None => true,
            Some(exts) => {
                let ext = Path::new(name)
                    .extension()
                    .map(|e| format!(".{}", e.to_string_lossy()))
                    .unwrap_or_default();
                exts.iter().any(|e| e == &ext)
            }
        }
    };

    let mut ignores = IgnoreRules::new();
    ignores.add_input(options.get("ignoreSet"));
    ignores.add_input(options.get("ignorePattern"));
    ignores.add_from_file(options.get("ignoreConfig"));
    if options.get("gitignore").and_then(|v| v.as_bool()).unwrap_or(false) {
        let gitignore_path = std::env::current_dir()
            .unwrap_or_default()
            .join(".gitignore");
        let val = Value::String(gitignore_path.to_string_lossy().into_owned());
        ignores.add_from_file(Some(&val));
    }
    ignores.build();

    let files = get_all_files(paths, &filter, &ignores);

    let verbose = options
        .get("verbose")
        .and_then(|v| v.as_i64())
        .unwrap_or(0) as u64;
    let silent = options.get("silent").and_then(|v| v.as_bool()).unwrap_or(false);
    let dry = options.get("dry").and_then(|v| v.as_bool()).unwrap_or(false);
    let run_in_band = options.get("runInBand").and_then(|v| v.as_bool()).unwrap_or(false);
    let babel = options.get("babel").and_then(|v| v.as_bool()).unwrap_or(false);

    let num_files = files.len();
    if num_files == 0 {
        write_stdout("No files selected, nothing to do. \n");
        return;
    }

    let processes = if run_in_band { 1 } else { num_files.min(cpus) };
    let chunk_size = if processes > 1 {
        ((num_files as f64) / processes as f64).ceil() as usize
    } else {
        num_files
    };

    if !silent {
        write_stdout(&format!("Processing {} files... \n", files.len()));
        if !run_in_band {
            write_stdout(&format!("Spawning {} workers...\n", processes));
        }
        if dry {
            write_stdout(&Colors::green("Running in dry mode, no files will be written! \n"));
        }
    }

    // Determine the bridge path relative to the executable directory.
    let bridge_path = bridge_path();

    let mut counters = Counters {
        error: 0,
        ok: 0,
        nochange: 0,
        skip: 0,
        stats: HashMap::new(),
    };

    let start = Instant::now();

    // next(): returns the next chunk of files, advancing the index.
    let mut index = 0usize;
    let mut next = || -> Vec<String> {
        if !silent && !run_in_band && index < num_files {
            let remaining = num_files - index;
            let n = chunk_size.min(remaining);
            write_stdout(&format!("Sending {} files to free worker...\n", n));
        }
        let take = chunk_size.min(num_files.saturating_sub(index));
        let chunk: Vec<String> = files[index..index + take].to_vec();
        index += take;
        chunk
    };

    let bridge_opts = opts_to_bridge(options);

    let mut workers: Vec<Worker> = Vec::with_capacity(processes);
    for _ in 0..processes {
        match spawn_worker(&bridge_path, transform_file, babel) {
            Ok(w) => workers.push(w),
            Err(e) => {
                let mut err = io::stderr().lock();
                let _ = writeln!(err, "Failed to spawn worker: {}", e);
                return;
            }
        }
    }

    // Send the initial chunk to each worker.
    for w in workers.iter_mut() {
        let chunk = next();
        let msg = json!({ "files": chunk, "options": bridge_opts });
        let _ = w.send(&msg);
    }

    // Service worker messages until all workers disconnect.
    let mut alive: Vec<usize> = (0..workers.len()).collect();
    let mut disconnected = vec![false; workers.len()];
    while alive.iter().any(|&i| !disconnected[i]) {
        // Read one line from each alive worker.
        let mut to_read = Vec::new();
        for &i in &alive {
            if !disconnected[i] {
                to_read.push(i);
            }
        }
        if to_read.is_empty() {
            break;
        }
        for i in to_read {
            if disconnected[i] {
                continue;
            }
            let mut line = String::new();
            match workers[i].reader.read_line(&mut line) {
                Ok(0) => {
                    // EOF: worker exited.
                    disconnected[i] = true;
                    let _ = workers[i].child.wait();
                }
                Ok(_) => {
                    let trimmed = line.trim_end_matches('\n');
                    if trimmed.is_empty() {
                        continue;
                    }
                    let msg: Value = match serde_json::from_str(trimmed) {
                        Ok(v) => v,
                        Err(_) => continue,
                    };
                    handle_message(
                        i,
                        &mut workers,
                        &mut next,
                        &mut counters,
                        &mut index,
                        num_files,
                        chunk_size,
                        silent,
                        run_in_band,
                        verbose,
                    }, msg);
                }
                Err(e) if e.kind() == io::ErrorKind::WouldBlock => {
                    // Should not happen for blocking pipes; spin-safe.
                }
                Err(_) => {
                    disconnected[i] = true;
                }
            }
        }
    }

    let time_elapsed = start.elapsed().as_secs_f64();
    let elapsed_str = format!("{:.3}", time_elapsed);

    if !silent {
        write_stdout("All done. \n");
        show_file_stats(&counters);
        show_stats(&counters.stats);
        write_stdout(&format!("Time elapsed: {}seconds \n", elapsed_str));

        if options.get("failOnError").and_then(|v| v.as_bool()).unwrap_or(false)
            && counters.error > 0
        {
            process::exit(1);
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn handle_message(
    i: usize,
    workers: &mut Vec<Worker>,
    next: &mut impl FnMut() -> Vec<String>,
    counters: &mut Counters,
    _index: &mut usize,
    _num_files: usize,
    _chunk_size: usize,
    _silent: bool,
    _run_in_band: bool,
    verbose: u64,
    msg: Value,
) {
    let action = msg.get("action").and_then(|v| v.as_str()).unwrap_or("");
    match action {
        "status" => {
            let status = msg.get("status").and_then(|v| v.as_str()).unwrap_or("");
            let m = msg.get("msg").and_then(|v| v.as_str()).unwrap_or("");
            match status {
                "error" => counters.error += 1,
                "ok" => counters.ok += 1,
                "nochange" => counters.nochange += 1,
                "skip" => counters.skip += 1,
                _ => {}
            }
            log_status(status, m, verbose);
        }
        "update" => {
            let name = msg.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string();
            let quantity = msg.get("quantity").and_then(|v| v.as_i64()).unwrap_or(1) as u64;
            *counters.stats.entry(name).or_insert(0) += quantity;
        }
        "free" => {
            let chunk = next();
            let bridge_opts = Value::Null; // placeholder; see below
            let _ = bridge_opts;
            // We need the bridge options; fetch from the outer scope via a
            // stored value. For simplicity, re-send with options carried in a
            // thread-local. See note in run_transform.
            let msg = json!({ "files": chunk, "options": bridge_opts_clone() });
            let _ = workers[i].send(&msg);
        }
        "report" => {
            let file = msg.get("file").and_then(|v| v.as_str()).unwrap_or("");
            let m = msg.get("msg").and_then(|v| v.as_str()).unwrap_or("");
            report(file, m);
        }
        _ => {}
    }
}

