// ----------------------------------------------------------------------------
// Helpers: bridge path, http transform download, executable entry
// ----------------------------------------------------------------------------

/// Resolve the absolute path to `bridge/transform-host.js`, searching first
/// next to the running executable (installed binary) and falling back to the
/// current working directory (development layout).
fn bridge_path() -> String {
    if let Ok(exe) = std::env::current_exe() {
        let candidate = exe
            .parent()
            .map(|p| p.join("bridge").join("transform-host.js"));
        if let Some(c) = candidate {
            if c.exists() {
                return c.to_string_lossy().into_owned();
            }
        }
    }
    // Development layout: workspace root holds the bridge directory.
    let candidates = [
        "bridge/transform-host.js",
        "../bridge/transform-host.js",
    ];
    for c in candidates {
        if Path::new(c).exists() {
            if let Ok(abs) = std::fs::canonicalize(c) {
                return abs.to_string_lossy().into_owned();
            }
            return c.to_string();
        }
    }
    "bridge/transform-host.js".to_string()
}

/// Download a remote transform to a temp file (mirror of Runner's http branch).
fn download_transform(url: &str) -> io::Result<String> {
    use std::net::TcpStream;
    let (host, path) = parse_url(url)?;
    let port = if url.starts_with("https://") { 443 } else { 80 };
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr)?;
    let req = format!(
        "GET {} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\nUser-Agent: jscodeshift\r\n\r\n",
        path, host
    );
    stream.write_all(req.as_bytes())?;
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf)?;

    // Split headers/body.
    let header_end = find_header_end(&buf);
