/// Set or clear the FD_CLOEXEC flag on `fd`.
fn set_cloexec(fd: i32, cloexec: bool) {
    // SAFETY: fcntl(F_GETFD/F_SETFD) on a valid fd.
    unsafe {
        let cur = libc::fcntl(fd, libc::F_GETFD);
        if cur < 0 {
            return;
        }
        let flags = if cloexec {
            cur | libc::FD_CLOEXEC
        } else {
            cur & !libc::FD_CLOEXEC
        };
        let _ = libc::fcntl(fd, libc::F_SETFD, flags);
    }
}

fn spawn_worker(bridge_path: &str, transform_file: &str, babel: bool) -> io::Result<Worker> {
    // Two pipes: parent_write -> child_read (work), child_write -> parent_read (results).
    let (cr, pw) = make_pipe()?;
    let (pr, cw) = make_pipe()?;"}

