// process.exit does not terminate cleanly while that handle exists, causing the
// parent to time out and SIGKILL the child. We mirror the original by tearing
// down both pipe streams (which removes the poll handles) and letting the
// process exit on its own when the loop becomes empty.
let finishing = false;
function finish() {
  if (finishing) return;
